    TargetedPos=dir+eye;
    C3DVector int_pos,normal_vec;
    float cam_rad;
    if(!pcam_man->GetCameraTools().IsLineOfSight(things,eye,dir+eye,int_pos,normal_vec,cam_rad,&phit_thing,NCameraModes::CTools::TEST_ALL,false)){
        if(fov_filter(int_pos)){
